def head(title):return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | NILKEEPR</title><meta name="description" content="NILKEEPR school compliance: disclosures, consent and read-only institutional oversight."><link rel="icon" href="assets/logo.png"><link rel="stylesheet" href="assets/fonts.css"><link rel="stylesheet" href="mono-source.css?v=m1"><link rel="stylesheet" href="mono.css?v=m1"></head>'''
