# Inner routes preserve all substantive existing content and controls.
for name in ['platform','data-and-consent','about','contact','privacy','terms','communications-consent','email-policy','transcript','404']:
 old=BeautifulSoup((B/(name+'.html')).read_text(),'html.parser');main=old.select_one('main')
 for el in list(main.select('.ath-index,.ath-role-track,.ath-about-document')):el.decompose()
 for el in main.select('[data-motion]'):el.attrs.pop('data-motion',None)
 for el in main.select('.ath-title'):el['class']=[c for c in el.get('class',[]) if c!='ath-title']
 if name=='platform':
  opening=main.select_one('.ath-opening');opening.replace_with(BeautifulSoup('<section class="mono-page-hero"><p class="kicker">[ THE SCHOOL PLATFORM ]</p><h1 class="reveal">A clear view.<br><mark>A defined role.</mark></h1><p>Tools for schools to follow self-reported NIL activity without managing the deal.</p></section>','html.parser'))
 for el in main.select('h1,h2'):el['class']=el.get('class',[])+['reveal']
 doc=main.select_one('.reading-document')
 if doc:
  toc=BeautifulSoup('<nav class="document-toc" aria-label="On this page"><p>[ ON THIS PAGE ]</p></nav>','html.parser').nav
  for i,h in enumerate(doc.select('h2')):
   h['id']=h.get('id',f'chapter-{i+1}');a=old.new_tag('a',href='#'+h['id']);a.string=h.get_text(' ',strip=True);toc.append(a)
  doc.insert_before(toc)
 # Source legal layout uses exact original text; practical content is not converted into decorative filler.
 inner=head(old.title.get_text().split('|')[0].strip())+'<body class="mono-inner route-'+name+'">'+nav+str(main)+footer+'<script src="exclusive.js"></script><script src="mono.js?v=m1"></script></body></html>'
 (R/(name+'.html')).write_text(inner)
(R/'production/monodrift/resources.json').write_text(json.dumps(resources,indent=2))
